#!/usr/bin/env python3
from urllib.parse import urlparse
import ipaddress
import socket
import urllib.request

REQUIRED_HEADERS = {
    "Content-Security-Policy",
    "Strict-Transport-Security",
    "X-Content-Type-Options",
    "Referrer-Policy"
}

def validate_target(url):
    parsed = urlparse(url)
    if parsed.scheme not in {"http", "https"}:
        raise ValueError("Only HTTP and HTTPS URLs are allowed")
    if not parsed.hostname:
        raise ValueError("Target URL must contain a hostname")
    infos = socket.getaddrinfo(parsed.hostname, parsed.port or (443 if parsed.scheme == "https" else 80), type=socket.SOCK_STREAM)
    addresses = {item[4][0] for item in infos}
    if not addresses:
        raise ValueError("Hostname did not resolve")
    for address in addresses:
        ip = ipaddress.ip_address(address)
        if not (ip.is_private or ip.is_loopback):
            raise ValueError(f"Target resolves to non-private address: {address}")
    return parsed

def check_headers(url, timeout=5):
    validate_target(url)
    request = urllib.request.Request(url, method="GET", headers={"User-Agent": "lab-security-checker/1.0"})
    with urllib.request.urlopen(request, timeout=timeout) as response:
        headers = {key: value for key, value in response.headers.items()}
        present = sorted(header for header in REQUIRED_HEADERS if header in headers)
        missing = sorted(REQUIRED_HEADERS - set(present))
        return {
            "target": url,
            "status": response.status,
            "present_headers": present,
            "missing_headers": missing
        }

if __name__ == "__main__":
    import argparse, json
    parser = argparse.ArgumentParser(description="Safe HTTP security-header check for private or loopback lab targets")
    parser.add_argument("url")
    parser.add_argument("--timeout", type=float, default=5.0)
    args = parser.parse_args()
    result = check_headers(args.url, timeout=args.timeout)
    print(json.dumps(result, indent=2))

