from __future__ import annotations

import ipaddress
import socket
from urllib.parse import urlparse


class TargetPolicyError(ValueError):
    pass


def resolve_private_addresses(hostname: str, port: int) -> set[str]:
    try:
        infos = socket.getaddrinfo(hostname, port, type=socket.SOCK_STREAM)
    except socket.gaierror as exc:
        raise TargetPolicyError(f"Unable to resolve target hostname: {hostname}") from exc
    addresses = {item[4][0] for item in infos}
    if not addresses:
        raise TargetPolicyError("Target hostname resolved to no addresses")
    return addresses


def validate_target(url: str) -> tuple[str, str, int]:
    parsed = urlparse(url)
    if parsed.scheme not in {"http", "https"}:
        raise TargetPolicyError("Only HTTP and HTTPS targets are supported")
    if not parsed.hostname:
        raise TargetPolicyError("Target URL must contain a hostname")
    if parsed.hostname.lower() != "localhost":
        try:
            ipaddress.ip_address(parsed.hostname)
        except ValueError as exc:
            raise TargetPolicyError("Use localhost or a literal IP address for this lab tool") from exc
    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    addresses = resolve_private_addresses(parsed.hostname, port)
    for address in addresses:
        ip = ipaddress.ip_address(address)
        if not (ip.is_private or ip.is_loopback):
            raise TargetPolicyError(
                f"Target resolves to a non-private address: {address}"
            )
    return parsed.scheme, parsed.hostname, port

from __future__ import annotations

import ssl
import urllib.error
import urllib.request
from http.cookies import SimpleCookie

from .models import Finding
from .policy import validate_target

RECOMMENDED_HEADERS = {
    "Content-Security-Policy": (
        "Missing Content-Security-Policy header",
        "Add a policy appropriate to the application and roll it out carefully, ideally after testing in report-only mode where supported.",
    ),
    "Strict-Transport-Security": (
        "Missing Strict-Transport-Security header",
        "For HTTPS applications, configure HSTS after confirming HTTPS coverage and certificate deployment are correct.",
    ),
    "X-Content-Type-Options": (
        "Missing X-Content-Type-Options header",
        "Send X-Content-Type-Options: nosniff where appropriate to reduce MIME-type confusion.",
    ),
    "Referrer-Policy": (
        "Missing Referrer-Policy header",
        "Choose and enforce a Referrer-Policy appropriate for the application's privacy and functionality requirements.",
    ),
}


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise urllib.error.HTTPError(req.full_url, code, "Redirect blocked by lab policy", headers, fp)


def _open(url: str, timeout: float):
    validate_target(url)
    request = urllib.request.Request(
        url,
        method="GET",
        headers={"User-Agent": "authorized-lab-security-audit/1.0"},
    )
    context = ssl.create_default_context()
    opener = urllib.request.build_opener(NoRedirect)
    if url.startswith("https://"):
        return opener.open(request, timeout=timeout, context=context)
    return opener.open(request, timeout=timeout)


def inspect_headers(url: str, timeout: float = 5.0) -> list[Finding]:
    findings: list[Finding] = []
    try:
        with _open(url, timeout) as response:
            headers = {key.lower(): value for key, value in response.headers.items()}
            for header, details in RECOMMENDED_HEADERS.items():
                if header == "Strict-Transport-Security" and not url.startswith("https://"):
                    continue
                title, remediation = details
                if header.lower() not in headers:
                    findings.append(
                        Finding(
                            id=f"HDR-{header.upper().replace('-', '')}",
                            title=title,
                            severity="low",
                            target=url,
                            description=f"The response did not include the {header} header.",
                            evidence=f"HTTP status={response.status}; missing header={header}",
                            remediation=remediation,
                        )
                    )
    except urllib.error.HTTPError as exc:
        findings.append(
            Finding(
                id="HTTP-STATUS",
                title="HTTP error response observed",
                severity="info",
                target=url,
                description="The target returned an HTTP error status during the non-destructive GET request.",
                evidence=f"HTTP status={exc.code}",
                remediation="Review whether the response is expected for the requested path; do not treat an error status alone as a vulnerability.",
                status="informational",
            )
        )
    return findings


def inspect_cookies(url: str, timeout: float = 5.0) -> list[Finding]:
    findings: list[Finding] = []
    with _open(url, timeout) as response:
        cookie_headers = response.headers.get_all("Set-Cookie") or []
        for raw in cookie_headers:
            jar = SimpleCookie()
            jar.load(raw)
            for morsel in jar.values():
                name = morsel.key
                raw_attributes = [part.strip().lower() for part in raw.split(";")[1:]]
                flags = {part.split("=", 1)[0].strip() for part in raw_attributes}
                if url.startswith("https://") and "secure" not in flags:
                    findings.append(
                        Finding(
                            id=f"COOKIE-SECURE-{name}",
                            title=f"Cookie {name} lacks Secure attribute",
                            severity="medium",
                            target=url,
                            description="A cookie was set over HTTPS without the Secure attribute.",
                            evidence=f"Set-Cookie present for cookie={name}; Secure attribute absent",
                            remediation="Set Secure on cookies that should only be transmitted over HTTPS.",
                        )
                    )
                if "httponly" not in flags:
                    findings.append(
                        Finding(
                            id=f"COOKIE-HTTPONLY-{name}",
                            title=f"Cookie {name} lacks HttpOnly attribute",
                            severity="low",
                            target=url,
                            description="A cookie was set without HttpOnly.",
                            evidence=f"Set-Cookie present for cookie={name}; HttpOnly attribute absent",
                            remediation="Set HttpOnly for session or authentication cookies that do not need client-side script access.",
                        )
                    )
    return findings
